package com.rapidwarning;

import com.google.inject.Provides;
import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.PlayerComposition;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.kit.KitType;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemVariationMapping;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@Slf4j
@PluginDescriptor(
	name = "Rapid Warning",
	description = "Warn if your Twisted bow or Zaryte crossbow is not on Rapid",
	tags = {"rapid", "attack", "style", "twisted", "bow", "zaryte", "crossbow", "ranged"}
)
public class RapidWarningPlugin extends Plugin
{
	public static final String CONFIG_GROUP = "rapidwarning";

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private RapidWarningOverlay overlay;

	@Inject
	private OverlayManager overlayManager;

	/** Every item id that resolves to a watched weapon, variations included. */
	private final Map<Integer, WatchedWeapon> weaponsByItemId = new HashMap<>();

	/**
	 * The warning message, non-null exactly when a watched weapon is equipped on
	 * the wrong style. The overlay reads this and nothing else, so no game state is
	 * touched from the render path.
	 */
	@Getter
	private String warningText;

	@Override
	protected void startUp()
	{
		buildWeaponLookup();
		overlayManager.add(overlay);
		clientThread.invoke(this::update);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		warningText = null;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			update();
		}
		else if (event.getGameState() == GameState.LOGIN_SCREEN)
		{
			warningText = null;
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		// COM_MODE is the selected attack-style button. The weapon category varbit
		// changes when you swap into a weapon whose combat tab has a different
		// layout, which can move the selection without COM_MODE itself changing.
		if (event.getVarpId() == VarPlayerID.COM_MODE
			|| event.getVarbitId() == VarbitID.COMBAT_WEAPON_CATEGORY)
		{
			update();
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		update();
	}

	/**
	 * Recompute the warning. Every input is event-driven, so there is no per-tick
	 * work and no GameTick subscription.
	 */
	private void update()
	{
		final WatchedWeapon weapon = weaponsByItemId.get(getEquippedWeaponId());

		if (weapon == null)
		{
			warningText = null;
			return;
		}

		final RangedStyle style = RangedStyle.fromIndex(client.getVarpValue(VarPlayerID.COM_MODE));

		if (style == weapon.getDesiredStyle())
		{
			warningText = null;
			return;
		}

		warningText = weapon.getDisplayName()
			+ " is on " + (style == null ? "an unknown style" : style.getDisplayName());
	}

	private Integer getEquippedWeaponId()
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return null;
		}

		final Player player = client.getLocalPlayer();
		if (player == null)
		{
			return null;
		}

		final PlayerComposition composition = player.getPlayerComposition();
		if (composition == null)
		{
			return null;
		}

		return composition.getEquipmentId(KitType.WEAPON);
	}

	/**
	 * Map every variation of each watched weapon onto its entry, so ornament kits
	 * and charged/beta variants resolve to the same weapon.
	 * <p>
	 * Both calls are total: map() normalises to the base id and falls back to
	 * identity, so a variant id in the enum still expands to its whole group, and
	 * getVariations() falls back to a singleton, so a weapon with no variation
	 * group is still registered under its own id.
	 */
	private void buildWeaponLookup()
	{
		weaponsByItemId.clear();

		for (WatchedWeapon weapon : WatchedWeapon.values())
		{
			final int baseId = ItemVariationMapping.map(weapon.getItemId());

			for (Integer itemId : ItemVariationMapping.getVariations(baseId))
			{
				weaponsByItemId.put(itemId, weapon);
			}
		}

		log.debug("Watching {} item ids: {}", weaponsByItemId.size(), weaponsByItemId.keySet());
	}

	@Provides
	RapidWarningConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(RapidWarningConfig.class);
	}
}

package com.rapidwarning;

import lombok.Getter;

/**
 * Attack style, identified by the index of its button in the combat tab.
 * <p>
 * VarPlayer COM_MODE holds <em>which button is selected</em> (0-3), not a global
 * style id. These indices are therefore only meaningful for the bow and crossbow
 * weapon categories, which both present exactly these three styles. Do not reuse
 * them for melee weapons, where the same index means something else entirely.
 */
@Getter
public enum RangedStyle
{
	ACCURATE(0, "Accurate"),
	RAPID(1, "Rapid"),
	LONGRANGE(3, "Longrange");

	private final int index;
	private final String displayName;

	RangedStyle(int index, String displayName)
	{
		this.index = index;
		this.displayName = displayName;
	}

	public static RangedStyle fromIndex(int index)
	{
		for (RangedStyle style : values())
		{
			if (style.index == index)
			{
				return style;
			}
		}

		return null;
	}
}

package com.rapidwarning;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(RapidWarningPlugin.CONFIG_GROUP)
public interface RapidWarningConfig extends Config
{
	@Alpha
	@ConfigItem(
		keyName = "overlayColor",
		name = "Overlay colour",
		description = "Overlay background colour"
	)
	default Color overlayColor()
	{
		return new Color(255, 0, 0, 150);
	}
}

package com.rapidwarning;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.TitleComponent;

class RapidWarningOverlay extends OverlayPanel
{
	private final RapidWarningPlugin plugin;
	private final RapidWarningConfig config;

	@Inject
	private RapidWarningOverlay(RapidWarningPlugin plugin, RapidWarningConfig config)
	{
		super(plugin);

		setPosition(OverlayPosition.ABOVE_CHATBOX_RIGHT);

		this.plugin = plugin;
		this.config = config;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		// The plugin decides whether there is a warning and what it says; the
		// overlay only draws it. No game state is read from the render path.
		final String text = plugin.getWarningText();

		if (text == null)
		{
			return null;
		}

		panelComponent.getChildren().clear();
		panelComponent.getChildren().add(TitleComponent.builder()
			.text(text)
			.color(Color.WHITE)
			.build());

		panelComponent.setPreferredSize(new Dimension(graphics.getFontMetrics().stringWidth(text) + 10, 0));
		panelComponent.setBackgroundColor(config.overlayColor());

		return super.render(graphics);
	}
}

package com.rapidwarning;

import lombok.Getter;

/**
 * The weapons this plugin watches, and the style each one should be left on.
 * <p>
 * The desired style is declared per weapon rather than as a shared constant on
 * purpose: because COM_MODE is a button index, a hardcoded "1" is only Rapid for
 * weapons that present the three ranged styles. Adding a row forces you to state
 * its own index instead of inheriting a coincidence.
 */
@Getter
public enum WatchedWeapon
{
	TWISTED_BOW(20997, "Twisted bow", RangedStyle.RAPID),
	ZARYTE_CROSSBOW(26374, "Zaryte crossbow", RangedStyle.RAPID);

	private final int itemId;
	private final String displayName;
	private final RangedStyle desiredStyle;

	WatchedWeapon(int itemId, String displayName, RangedStyle desiredStyle)
	{
		this.itemId = itemId;
		this.displayName = displayName;
		this.desiredStyle = desiredStyle;
	}
}
